func TestNewClient_ConfiguresRawClient(t *testing.T) {
	t.Parallel()

	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/ping" {
			t.Fatalf("unexpected path: %s", r.URL.Path)
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"ok":true}`))
	}))
	t.Cleanup(srv.Close)

	client, err := NewClient(pipedrive.Config{
		BaseURL:    srv.URL,
		HTTPClient: srv.Client(),
	})
	if err != nil {
		t.Fatalf("NewClient error: %v", err)
	}

	var out struct {
		Ok bool `json:"ok"`
	}
	if err := client.Raw.Do(context.Background(), http.MethodGet, "/ping", nil, nil, &out); err != nil {
		t.Fatalf("raw do error: %v", err)
	}
	if !out.Ok {
		t.Fatalf("expected ok=true")
	}
}

type stubRoundTripper func(*http.Request) (*http.Response, error)

func (f stubRoundTripper) RoundTrip(r *http.Request) (*http.Response, error) { return f(r) }

// The default base URL must still pin credentials: NewClient backfills the
// resolved base URL into the config so an empty BaseURL does not leave the
// auth middleware unpinned.
func TestNewClient_DefaultBaseURLPinsCredentials(t *testing.T) {
	t.Parallel()

	var attackerHeaders http.Header
	stub := stubRoundTripper(func(r *http.Request) (*http.Response, error) {
		if r.URL.Host == "attacker.example" {
			attackerHeaders = r.Header.Clone()
			return &http.Response{
				StatusCode: 200,
				Header:     make(http.Header),
				Body:       io.NopCloser(strings.NewReader(`{}`)),
				Request:    r,
			}, nil
		}
		h := make(http.Header)
		h.Set("Location", "https://attacker.example/steal")
		return &http.Response{
			StatusCode: http.StatusFound,
			Header:     h,
			Body:       io.NopCloser(strings.NewReader("")),
			Request:    r,
		}, nil
	})

	client, err := NewClient(pipedrive.Config{
		HTTPClient: &http.Client{Transport: stub},
		Auth:       pipedrive.APITokenAuth("secret-token"),
	})
	if err != nil {
		t.Fatalf("NewClient error: %v", err)
	}

	_ = client.Raw.Do(context.Background(), http.MethodGet, "/deals", nil, nil, nil)

	if attackerHeaders == nil {
		t.Fatal("expected the redirect to be followed to the attacker host")
	}
	if got := attackerHeaders.Get("x-api-token"); got != "" {
		t.Fatalf("credentials leaked with default base URL: %q", got)
	}
}

func TestNewClient_InvalidOAuthBaseURLFails(t *testing.T) {
	t.Parallel()

	_, err := NewClient(pipedrive.Config{
		BaseURL:      "https://api.example.test",
		OAuthBaseURL: "missing-scheme-and-host",
	})
	if err == nil {
		t.Fatal("expected an error for an invalid OAuth base URL")
	}
}
package pipedrive

import "net/http"

type Config struct {
	// BaseURL is the API origin requests are sent to. When set, credentials
	// from Auth are only attached to requests targeting this origin (scheme
	// and host), including redirect hops — a cross-origin redirect target
	// never receives them. When empty, Auth applies to every request made
	// through the client, but a redirect that leaves the initial request's
	// origin still suppresses credentials on that hop.
	//
	// The value must be an absolute URL with a scheme and host, e.g.
	// "https://api.pipedrive.com". A value that lacks either fails closed:
	// credentials are withheld from every request rather than sent
	// somewhere unintended, which surfaces as authentication errors from
	// the API. v1/v2 NewClient reject such values; NewHTTPClient cannot
	// return an error, so it withholds silently.
	BaseURL string

	// OAuthBaseURL is the origin the v1 OAuth service uses for authorize
	// URLs and token exchange/refresh. Empty uses the production default
	// (https://oauth.pipedrive.com). Requests to it authenticate with
	// explicit client credentials; Auth is never attached.
	OAuthBaseURL string

	HTTPClient *http.Client

	Middleware []Middleware

	RetryPolicy *RetryPolicy

	// MaxResponseSize caps successful response bodies in bytes.
	// Zero uses the default 64 MiB cap. Negative values disable the cap.
	MaxResponseSize int64

	UserAgent string
	Auth      AuthProvider
}

func NewHTTPClient(cfg Config) *http.Client {
	base := cfg.HTTPClient
	if base == nil {
		base = http.DefaultClient
	}

	clone := new(http.Client)
	*clone = *base

	transport := clone.Transport
	if transport == nil {
		transport = http.DefaultTransport
	}

	origin := authOriginFromBaseURL(cfg.BaseURL)

	middleware := make([]Middleware, 0, len(cfg.Middleware)+2)
	middleware = append(middleware, cfg.Middleware...)
	if cfg.UserAgent != "" {
		middleware = append(middleware, userAgentMiddleware(cfg.UserAgent))
	}
	if cfg.Auth != nil {
		middleware = append(middleware, authMiddleware(cfg.Auth, origin))
	}

	// Catches credential headers set directly on the request (for example
	// through WithHeader), which the auth middleware never sees, and marks
	// off-scope hops so the middleware does not re-attach Auth credentials.
	clone.CheckRedirect = redirectCredentialGuard(origin, base.CheckRedirect)

	transport = newResponseLimitTransport(transport, cfg.MaxResponseSize)
	transport = chainMiddleware(transport, middleware)

	policy := cfg.RetryPolicy
	if policy == nil {
		p := DefaultRetryPolicy()
		policy = &p
	}
	transport = newRetryTransport(transport, *policy, retryTransportOptions{})

	clone.Transport = transport
	return clone
}
