func TestFilesService_Add(t *testing.T) {
	t.Parallel()

	content := []byte("file contents")
	path := t.TempDir() + "/upload.txt"
	if err := os.WriteFile(path, content, 0o600); err != nil {
		t.Fatalf("write test file: %v", err)
	}

	fileReader, err := os.Open(path)
	if err != nil {
		t.Fatalf("open test file: %v", err)
	}
	t.Cleanup(func() { _ = fileReader.Close() })

	attempts := 0
	client := newTestClient(t, func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			t.Fatalf("unexpected method: %s", r.Method)
		}
		if r.URL.Path != "/files" {
			t.Fatalf("unexpected path: %s", r.URL.Path)
		}
		reader, err := r.MultipartReader()
		if err != nil {
			t.Fatalf("multipart reader: %v", err)
		}
		part, err := reader.NextPart()
		if err != nil {
			t.Fatalf("multipart part: %v", err)
		}
		if part.FormName() != "file" {
			t.Fatalf("unexpected form name: %q", part.FormName())
		}
		if part.FileName() != "upload.txt" {
			t.Fatalf("unexpected file name: %q", part.FileName())
		}
		body, err := io.ReadAll(part)
		if err != nil {
			t.Fatalf("read part: %v", err)
		}
		if !bytes.Equal(body, content) {
			t.Fatalf("unexpected file contents: %q", body)
		}

		attempts++
		if attempts == 1 {
			w.WriteHeader(http.StatusTooManyRequests)
			return
		}

		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":12,"name":"upload.txt"}}`))
	})

	file, err := client.Files.Add(context.Background(), "upload.txt", fileReader)
	if err != nil {
		t.Fatalf("Add error: %v", err)
	}
	if attempts != 2 {
		t.Fatalf("expected 2 upload attempts, got %d", attempts)
	}
	if file.ID != 12 || file.Name != "upload.txt" {
		t.Fatalf("unexpected file: %#v", file)
	}
}

func TestFilesService_AddRemoteFile(t *testing.T) {
	t.Parallel()

	client := newTestClient(t, func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			t.Fatalf("unexpected method: %s", r.Method)
		}
		if r.URL.Path != "/files/remote" {
			t.Fatalf("unexpected path: %s", r.URL.Path)
		}
		if got := r.Header.Get("Content-Type"); got != "application/x-www-form-urlencoded" {
			t.Fatalf("unexpected content type: %q", got)
		}
		if err := r.ParseForm(); err != nil {
			t.Fatalf("parse form: %v", err)
		}
		if got := r.Form.Get("file_type"); got != "gdoc" {
			t.Fatalf("unexpected file_type: %q", got)
		}
		if got := r.Form.Get("item_type"); got != "deal" {
			t.Fatalf("unexpected item_type: %q", got)
		}

		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":33,"name":"remote"}}`))
	})

	form := url.Values{}
	form.Set("file_type", "gdoc")
	form.Set("item_type", "deal")
	form.Set("item_id", "1")
	file, err := client.Files.AddRemoteFile(context.Background(), form)
	if err != nil {
		t.Fatalf("AddRemoteFile error: %v", err)
	}
	if file.ID != 33 {
		t.Fatalf("unexpected file: %#v", file)
	}
}


func (s *FilesService) Get(ctx context.Context, id FileID, opts ...FilesOption) (*File, error) {
	if err := validateID(id, "file id"); err != nil {
		return nil, err
	}
	cfg := newFilesOptions(opts)
	path := fmt.Sprintf("/files/%d", id)

	var payload struct {
		Data *File `json:"data"`
	}
	if err := s.client.Raw.Do(ctx, http.MethodGet, path, cfg.query, nil, &payload, cfg.requestOptions...); err != nil {
		return nil, err
	}
	if payload.Data == nil {
		return nil, fmt.Errorf("missing file data in response")
	}
	return payload.Data, nil
}

// Add uploads content as a file with fileName.
//
// The content is encoded into a replayable multipart request before it is
// sent, so retry policies can safely resend uploads after a rate-limit or
// transient response.
func (s *FilesService) Add(ctx context.Context, fileName string, content io.Reader, opts ...FilesOption) (*File, error) {
	if fileName == "" || content == nil {
		return nil, fmt.Errorf("file name and content are required")
	}

	contentType, body, err := multipartbody.NewFile("file", fileName, content)
	if err != nil {
		return nil, err
	}

	return s.AddRaw(ctx, body, contentType, opts...)
}

// AddRaw sends a pre-encoded multipart file request.
//
// Add is preferred for ordinary uploads because it creates a replayable
// request body that can be retried safely. AddRaw is available for callers
// that need to provide additional multipart fields themselves.
func (s *FilesService) AddRaw(ctx context.Context, body io.Reader, contentType string, opts ...FilesOption) (*File, error) {
	cfg := newFilesOptions(opts)
	if body == nil {
		return nil, fmt.Errorf("file body is required")
	}
	if contentType == "" {
		return nil, fmt.Errorf("content type is required")
	}

	reqOpts := append([]pipedrive.RequestOption{}, cfg.requestOptions...)
	reqOpts = append(reqOpts, pipedrive.WithHeader("Content-Type", contentType))

	var payload struct {
		Data *File `json:"data"`
	}
	if err := s.client.Raw.Do(ctx, http.MethodPost, "/files", cfg.query, body, &payload, reqOpts...); err != nil {
		return nil, err
	}
	if payload.Data == nil {
		return nil, fmt.Errorf("missing file data in response")
	}
	return payload.Data, nil
}

